export function getZamaFheErrorMessage(code: ZamaFheError): string {
  return zamaFheErrorMessages[code];
}

/** True when an instruction failed with one of these codes, whichever app program raised it. */
export function isZamaFheError(error: unknown, code?: ZamaFheError): boolean {
  if (!isSolanaError(error, SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM)) return false;
  return code === undefined ? error.context.code in zamaFheErrorMessages : error.context.code === code;
}
